const input = $input.first().json;
const rawPayload = input.body?.payload ?? input.payload;

if (!rawPayload) {
  throw new Error('Payload ausente');
}

const event = typeof rawPayload === 'string'
  ? JSON.parse(rawPayload)
  : rawPayload;

const allowedEvents = new Set(['PageView', 'InitiateCheckout']);
if (!allowedEvents.has(event.event_name)) {
  throw new Error('Evento não permitido');
}

const allowedSource = 'https://joaomota27.github.io/manualcriativo-site/it/';
if (!String(event.event_source_url || '').startsWith(allowedSource)) {
  throw new Error('Origem não permitida');
}

if (!event.event_id || !event.event_time) {
  throw new Error('event_id ou event_time ausente');
}

const headers = input.headers ?? {};
const forwardedFor = headers['x-forwarded-for'] ?? headers['x-real-ip'] ?? '';
const clientIp = String(forwardedFor).split(',')[0].trim();

const userData = {
  fbc: event.user_data?.fbc || undefined,
  fbp: event.user_data?.fbp || undefined,
  client_user_agent: event.user_agent || headers['user-agent'] || undefined,
  client_ip_address: clientIp || undefined,
};

Object.keys(userData).forEach((key) => {
  if (userData[key] === undefined || userData[key] === null || userData[key] === '') {
    delete userData[key];
  }
});

return [{
  json: {
    data: [{
      event_name: event.event_name,
      event_time: Number(event.event_time),
      event_id: String(event.event_id),
      action_source: 'website',
      event_source_url: event.event_source_url,
      user_data: userData,
      custom_data: event.custom_data ?? {},
    }],
  },
}];
